from supplier_loop.round_state.models import RoundState
from supplier_loop.simulator.port import BomLine, SupplierEntry


def bom_material_ids(state: RoundState) -> frozenset[str]:
    return frozenset(line.material_id for line in state.rfq.assignment.line_items)


def relevant_supplier_ids(state: RoundState) -> frozenset[str]:
    materials = bom_material_ids(state)
    return frozenset(
        entry.supplier_id for entry in state.rfq.directory if materials & set(entry.material_ids)
    )


def supplier_catalog(state: RoundState, supplier_id: str) -> frozenset[str]:
    for entry in state.rfq.directory:
        if entry.supplier_id == supplier_id:
            return frozenset(entry.material_ids)
    return frozenset()


def bom_lines_for_supplier(state: RoundState, supplier_id: str) -> list[BomLine]:
    catalog = supplier_catalog(state, supplier_id)
    return [line for line in state.rfq.assignment.line_items if line.material_id in catalog]


def supplier_for_address(state: RoundState, from_address: str) -> SupplierEntry | None:
    lowered = from_address.casefold()
    for entry in state.rfq.directory:
        if entry.email.casefold() == lowered:
            return entry
    return None

from supplier_loop.relevance import bom_lines_for_supplier
from supplier_loop.round_state.models import AsSentQuote, RoundState


def missing_lines(quote_as_sent: AsSentQuote, state: RoundState, supplier_id: str) -> list[str]:
    catalog = {line.material_id for line in bom_lines_for_supplier(state, supplier_id)}
    quoted = {line.material_id for line in quote_as_sent.line_items if line.material_id is not None}
    return sorted(material_id for material_id in catalog if material_id not in quoted)


def quantity_mismatches(
    quote_as_sent: AsSentQuote, state: RoundState, supplier_id: str
) -> list[tuple[str, float]]:
    quote_by_material = {
        line.material_id: line.quantity
        for line in quote_as_sent.line_items
        if line.material_id is not None
    }
    mismatches: list[tuple[str, float]] = []
    for bom_line in bom_lines_for_supplier(state, supplier_id):
        quoted_qty = quote_by_material.get(bom_line.material_id)
        if quoted_qty is not None and quoted_qty != bom_line.quantity:
            mismatches.append((bom_line.material_id, quoted_qty))
    return mismatches


def bom_quantity(state: RoundState, supplier_id: str, material_id: str) -> float:
    for bom_line in bom_lines_for_supplier(state, supplier_id):
        if bom_line.material_id == material_id:
            return bom_line.quantity
    return 0.0

from supplier_loop.machine.constants import (
    REMINDER_THRESHOLD_SIM_SECONDS,
    VALIDITY_ALARM_MARGIN_DAYS,
)
from supplier_loop.relevance import relevant_supplier_ids
from supplier_loop.round_state.models import RoundState, SupplierFacts


def due_alarms(state: RoundState) -> list[str]:
    alarms: list[str] = []
    if _has_reminder_due(state):
        alarms.append("reminder_due")
    if _has_validity_alarm(state):
        alarms.append("validity_alarm")
    return alarms


def reminder_is_due(supplier: SupplierFacts, sim_time: float) -> bool:
    if supplier.reminder_sim_time is not None:
        return False
    if supplier.phase not in {"awaiting_quote", "rfq_sent"}:
        return False
    if supplier.awaiting_since_sim_time is None:
        return False
    return sim_time - supplier.awaiting_since_sim_time >= REMINDER_THRESHOLD_SIM_SECONDS


def _has_reminder_due(state: RoundState) -> bool:
    sim_time = state.rfq.clock.sim_time_seconds
    for supplier_id in relevant_supplier_ids(state):
        supplier = state.suppliers[supplier_id]
        if reminder_is_due(supplier, sim_time):
            return True
    return False


def _has_validity_alarm(state: RoundState) -> bool:
    sim_days = state.rfq.clock.sim_time_days
    for supplier_id in relevant_supplier_ids(state):
        supplier = state.suppliers[supplier_id]
        if supplier.phase not in {"quoted", "escalated"} or supplier.quote is None:
            continue
        if supplier.quote_received_sim_days is None:
            continue
        document = supplier.quote.revised_as_sent or supplier.quote.as_sent
        expiry = supplier.quote_received_sim_days + document.validity_days
        if expiry - sim_days <= VALIDITY_ALARM_MARGIN_DAYS:
            return True
    return False

