import hashlib

from supplier_loop.simulator.port import EmailMessage


def quote_fingerprint(message: EmailMessage) -> str:
    attachments = ",".join(sorted(message.attachment_ids))
    payload = "\n".join(
        [message.from_address.casefold(), message.subject, message.body, attachments]
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()

from supplier_loop.machine.discrepancy import bom_quantity, missing_lines, quantity_mismatches
from supplier_loop.round_state.models import RoundState, SupplierFacts
from supplier_loop.simulator.port import Simulator


def correct_once(
    supplier: SupplierFacts,
    state: RoundState,
    simulator: Simulator,
    class_num: int,
) -> bool:
    if supplier.correction_used or supplier.quote is None:
        return False
    body = _correction_body(class_num, supplier, state)
    subject = f"Correction needed for {state.rfq.assignment.rfq_id}"
    email_id = simulator.send_email(supplier.email, subject, body)
    supplier.outbound_ids.append(email_id)
    supplier.correction_used = True
    return True


def _correction_body(class_num: int, supplier: SupplierFacts, state: RoundState) -> str:
    assignment = state.rfq.assignment
    as_sent = supplier.quote.as_sent if supplier.quote is not None else None
    if supplier.quote is not None and supplier.quote.revised_as_sent is not None:
        as_sent = supplier.quote.revised_as_sent
    if as_sent is None:
        return "Please correct your quote and resend it in this thread."
    if class_num == 1:
        missing = missing_lines(as_sent, state, supplier.supplier_id)
        return (
            f"Please add the missing line(s) to your quote: {', '.join(missing)}. "
            f"Resend the revised quote in this thread."
        )
    if class_num == 2:
        mismatches = quantity_mismatches(as_sent, state, supplier.supplier_id)
        parts = []
        for material_id, quoted_qty in mismatches:
            bom_qty = bom_quantity(state, supplier.supplier_id, material_id)
            parts.append(f"{material_id} must be {bom_qty:g} not {quoted_qty:g}")
        return (
            f"Please correct quantity on: {'; '.join(parts)}. "
            f"Resend the revised quote in this thread."
        )
    if class_num == 3:
        return (
            f"Please update payment terms to {assignment.required_payment_terms}. "
            f"Resend the revised quote in this thread."
        )
    if class_num == 4:
        return (
            f"Please extend validity to at least {assignment.required_validity_days} days. "
            f"Resend the revised quote in this thread."
        )
    return "Please correct your quote and resend it in this thread."

import re

from supplier_loop.quote_pipeline.recompute import recomputed_grand_total, recomputed_line_total
from supplier_loop.round_state.models import RoundState, SupplierFacts
from supplier_loop.simulator.port import EmailMessage, Simulator

_AMOUNT = re.compile(r"\d{1,3}(?:,\d{3})*(?:\.\d+)?|\d+(?:\.\d+)?")


def negotiate_once(
    supplier: SupplierFacts,
    state: RoundState,
    simulator: Simulator,
) -> bool:
    if supplier.quote is None or supplier.negotiation_used:
        return False
    target_total = compute_target_total(supplier, state)
    body = f"Your price is above our ceiling. We can do {target_total:,.2f} total for this quote."
    subject = f"Counter-offer for {state.rfq.assignment.rfq_id}"
    email_id = simulator.send_email(supplier.email, subject, body)
    supplier.outbound_ids.append(email_id)
    supplier.negotiation_used = True
    supplier.negotiation_target_total = target_total
    return True


def compute_target_total(supplier: SupplierFacts, state: RoundState) -> float:
    quote = supplier.quote
    if quote is None:
        return 0.0
    ceiling_pct = state.rfq.assignment.target_price_ceiling_pct
    history = {
        row.material_id: row.last_accepted_unit_price
        for row in state.rfq.price_history
        if row.supplier_id == supplier.supplier_id
    }
    line_totals: list[float] = []
    for line in quote.as_sent.line_items:
        if line.material_id is None:
            unit_price = line.unit_price
        else:
            last_accepted = history.get(line.material_id, line.unit_price)
            unit_price = last_accepted * (1 + ceiling_pct / 100)
        line_totals.append(recomputed_line_total(line.quantity, unit_price))
    return recomputed_grand_total(line_totals)


def record_negotiation_reply(supplier: SupplierFacts, message: EmailMessage | None = None) -> None:
    if supplier.quote is None:
        return
    if not supplier.own_quote_history:
        supplier.own_quote_history.append(supplier.quote.as_sent.model_copy(deep=True))
    if message is not None:
        supplier.negotiation_reply_total = parse_reply_total(message.body)


def parse_reply_total(body: str) -> float | None:
    match = _AMOUNT.search(body)
    if match is None:
        return None
    return float(match.group(0).replace(",", ""))

from supplier_loop.machine.discrepancy import missing_lines, quantity_mismatches
from supplier_loop.round_state.models import AsSentQuote, QuoteRecord, RoundState, SupplierFacts
from supplier_loop.simulator.port import Assignment, SentEmailRecord, Simulator


def send_pending_escalations(
    supplier: SupplierFacts,
    state: RoundState,
    simulator: Simulator,
    sent: list[SentEmailRecord],
) -> None:
    if supplier.quote is None:
        return
    approver = state.rfq.assignment.approver_email
    for class_num in _escalation_classes_to_send(supplier.escalation_classes):
        revised = _use_revised_marker(supplier, class_num)
        if _escalation_sent(supplier.supplier_id, class_num, sent, approver, revised=revised):
            continue
        body = _escalation_body(class_num, supplier, state, revised=revised)
        subject = f"[REF:{supplier.supplier_id}] class {class_num}"
        email_id = simulator.send_email(approver, subject, body)
        supplier.outbound_ids.append(email_id)


def _use_revised_marker(supplier: SupplierFacts, class_num: int) -> bool:
    return (
        supplier.correction_used
        and supplier.quote is not None
        and supplier.quote.revised_as_sent is not None
        and class_num in {1, 2, 3, 4}
    )


def _escalation_classes_to_send(classes: list[int]) -> list[int]:
    ordered: list[int] = []
    for class_num in (1, 2, 3, 4, 7, 6):
        if class_num in classes:
            ordered.append(class_num)
    return ordered


def _escalation_sent(
    supplier_id: str,
    class_num: int,
    sent: list[SentEmailRecord],
    approver_email: str,
    *,
    revised: bool = False,
) -> bool:
    ref = f"[REF:{supplier_id}]"
    marker = _class_marker(class_num, revised=revised)
    return any(
        mail.to == approver_email and ref in mail.subject and marker in mail.body for mail in sent
    )


def _class_marker(class_num: int, *, revised: bool = False) -> str:
    if revised:
        return f"Class {class_num} (revised):"
    return f"Class {class_num}:"


def _escalation_body(
    class_num: int,
    supplier: SupplierFacts,
    state: RoundState,
    *,
    revised: bool = False,
) -> str:
    quote = supplier.quote
    if quote is None:
        return f"{_class_marker(class_num, revised=revised)} discrepancy requires approver review."
    as_sent = quote.revised_as_sent or quote.as_sent
    assignment = state.rfq.assignment
    marker = _class_marker(class_num, revised=revised)
    specific = _class_specific_claim(class_num, as_sent, state, supplier)
    if revised:
        return f"{marker} {specific} {_quote_now_on_file(as_sent, assignment)}"
    return f"{marker} {specific}"


def _class_specific_claim(
    class_num: int,
    as_sent: AsSentQuote,
    state: RoundState,
    supplier: SupplierFacts,
) -> str:
    assignment = state.rfq.assignment
    if class_num == 1:
        missing = missing_lines(as_sent, state, supplier.supplier_id)
        if missing:
            return f"missing BOM line(s): {', '.join(missing)}."
        return "required BOM lines are present."
    if class_num == 2:
        mismatches = quantity_mismatches(as_sent, state, supplier.supplier_id)
        if mismatches:
            parts = [f"{material_id} quoted {qty:g}" for material_id, qty in mismatches]
            return f"quantity mismatch on {', '.join(parts)}."
        return "quoted quantities match the BOM."
    if class_num == 3:
        return (
            f"payment terms {as_sent.payment_terms!r} "
            f"differs from required {assignment.required_payment_terms!r}."
        )
    if class_num == 4:
        return (
            f"validity {as_sent.validity_days} days "
            f"is shorter than required {assignment.required_validity_days} days."
        )
    if class_num == 6:
        original = supplier.quote.recomputed_grand_total if supplier.quote is not None else 0.0
        target = supplier.negotiation_target_total
        reply = supplier.negotiation_reply_total
        parts = [f"original {original:,.2f}"]
        if target is not None:
            parts.append(f"counter {target:,.2f}")
        if reply is not None:
            parts.append(f"supplier reply {reply:,.2f}")
        return "negotiation outcome " + ", ".join(parts) + "."
    if class_num == 7:
        return "supplier content contains embedded instructions."
    return "discrepancy requires approver review."


def _quote_now_on_file(as_sent: AsSentQuote, assignment: Assignment) -> str:
    lines = ", ".join(
        f"{line.material_id or line.description} qty {line.quantity:g} at {line.unit_price:g}"
        for line in as_sent.line_items
    ) or "no lines"
    return (
        f"Quote now on file: {lines}; "
        f"terms {as_sent.payment_terms!r} (required {assignment.required_payment_terms!r}); "
        f"validity {as_sent.validity_days} days (required {assignment.required_validity_days})."
    )

